    """Extend short rightmost horizontal streaks in red (1)."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg_counts = {v:n for v,n in counts.items() if v != bg}
    if not fg_counts:
        return out
    fg = max(fg_counts, key=fg_counts.get)
    # Some rows encode a down-right continuation: place the red point two
    # columns beyond each of two diagonally stepping right endpoints.
    ends = []
    for row in grid:
        cols = [c for c,v in enumerate(row) if v == fg]
        ends.append(max(cols) if cols else None)
    diagonal_rows = set()
    for r in range(h-1):
        p, q = ends[r], ends[r+1]
        if p is not None and q == p + 1 and p + 2 < w and q + 2 < w:
            # Only when both continuation cells are background.
            if grid[r][p+2] == bg and grid[r+1][q+2] == bg:
                out[r][p+2] = 1
                out[r+1][q+2] = 1
                diagonal_rows.update((r, r+1))
    for r, row in enumerate(grid):
        if r in diagonal_rows:
            continue
        cols = [c for c,v in enumerate(row) if v == fg]
        if not cols:
            continue
        right = max(cols)
        # A solid foreground prefix with an empty suffix is extended to the edge.
        if row[0] == fg:
            prefix = 0
            while prefix < w and row[prefix] == fg:
                prefix += 1
            if prefix < w and all(v == bg for v in row[prefix:]):
                for c in range(prefix, w):
                    out[r][c] = 1
                continue
        # If a row contains only a background prefix followed by a foreground
        # block at the right border, recolor that terminal block.
        if right == w-1:
            start = right
            while start >= 0 and row[start] == fg:
                start -= 1
            if all(v == bg for v in row[:start+1]) and start >= 0:
                for c in range(start+1, w):
                    out[r][c] = 1
            continue
        # Extend rows whose final contiguous foreground block is a short bar.
